        .collect();
    let rows = layout
        .iter()
        .zip(values)
        .map(|(meta, v)| {
            let class = if meta.input_derived {
                RowClass::InputDerived
            } else if let Some(x) = v.value() {
                classify_row(x, scales[meta.body as usize][meta.kind.index()])?
